previewCss:
.darma-loader-darma-b7-card-flip-stack { --accent: var(--loader-color, #f43f5e); --accent-2: var(--loader-secondary-color, #fb923c); width: calc(var(--loader-size, 80px) * .8); height: var(--loader-size, 80px); position: relative; perspective: 500px; }
.darma-loader-darma-b7-card-flip-stack span { position: absolute; inset: 0; border-radius: 14%; background: linear-gradient(135deg, var(--accent), var(--accent-2)); transform-origin: center top; animation: darma-loader-darma-b7-card-flip-stack-flip calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-darma-b7-card-flip-stack span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .28); opacity: .78; }
.darma-loader-darma-b7-card-flip-stack span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .56); opacity: .55; }
@keyframes darma-loader-darma-b7-card-flip-stack-flip { 0%, 55%, 100% { transform: rotateX(0deg); } 28% { transform: rotateX(-172deg); } }

